// components/Profile.js
import { useTab } from '../context/TabContext';
import { useAuth } from '../context/AuthContext';

const Profile = ({ onNavigate }) => {
  const { user, logout, cart, removeFromCart } = useAuth();
  const { activeTab, changeTab } = useTab(); // ✅ Используем контекст вместо локального состояния

  // УДАЛЯЕМ локальный useState и useEffect для activeTab
  const [checkoutData, setCheckoutData] = useState({
    cardNumber: '',
    address: ''
  });

  // ✅ Функция навигации с проверкой
  const safeNavigate = (page) => {
    if (onNavigate && typeof onNavigate === 'function') {
      onNavigate(page);
    } else {
      window.location.hash = page;
    }
  };

  if (!user) {
    return (
      <div className="max-w-md mx-auto mt-16 p-8 text-center">
        <p className="text-lg mb-4">Пожалуйста, войдите в систему</p>
        <button 
          onClick={() => safeNavigate('./catalog')}
          className="bg-gold-600 text-white px-6 py-3 rounded hover:bg-gold-700"
        >
          Войти / Зарегистрироваться
        </button>
      </div>
    );
  }

  const handleCheckout = (e) => {
    e.preventDefault();
    alert('Заказ оформлен! Спасибо за покупку.');
    cart.forEach(item => removeFromCart(item.id));
  };

  const totalPrice = cart.reduce((sum, item) => sum + (item.price * (item.quantity || 1)), 0);

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      <h1 className="text-3xl font-serif font-bold mb-8">Личный кабинет</h1>

      {/* Tabs */}
      <div className="border-b mb-8">
        <div className="flex space-x-8">
          {['profile', 'cart', 'favorites', 'orders'].map(tab => (
            <button
              key={tab}
              onClick={() => changeTab(tab)} // ✅ Используем changeTab из контекста
              className={`pb-4 px-2 capitalize ${
                activeTab === tab 
                  ? 'border-b-2 border-gold-600 text-gold-600 font-semibold' 
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              {tab === 'profile' ? 'Профиль' : 
               tab === 'cart' ? 'Корзина' : 
               tab === 'favorites' ? 'Понравилось' : 'Заказы'}
            </button>
          ))}
        </div>
      </div>

      {/* Остальной код остается таким же */}
      {/* ... */}
    </div>
  );
};

export default Profile;
